// About dialog and update hint: versions, the bundled FFmpeg build and its source, the third-party
// notices (THIRD_PARTY_NOTICES.txt, generated by scripts/third-party-notices.mjs) and the check for
// a newer release on GitHub (src/main/updateCheck.ts).
import { app, ipcMain, net } from 'electron'
import { existsSync, readFileSync } from 'node:fs'
import { readFile, stat } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { LATEST_RELEASE_API, REPO_URL, type AboutInfo, type UpdateStatus } from '@shared/about'
import type { AppSettingsStore } from './appSettings'
import type { Ffmpeg } from './ffmpeg'
import { checkForUpdate, type FetchLike } from './updateCheck'

const NOTICES = 'THIRD_PARTY_NOTICES.txt'

/** package.json's version; a development run started on a script file has no app package.json. */
export function appVersion(): string {
  if (app.isPackaged) return app.getVersion()
  for (const dir of [app.getAppPath(), process.cwd()]) {
    try {
      const pkg = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8')) as { name?: string; version?: string }
      if (pkg.name === 'diashow-studio' && pkg.version) return pkg.version
    } catch {
      // not here
    }
  }
  return app.getVersion()
}

/** Folders that may hold the generated notices: next to the exe, resources, or vendor/ in development. */
function noticeCandidates(): string[] {
  if (app.isPackaged) return [join(dirname(process.execPath), NOTICES), join(process.resourcesPath, NOTICES)]
  return [join(app.getAppPath(), 'vendor', NOTICES), join(process.cwd(), 'vendor', NOTICES)]
}

async function readNotices(): Promise<string | null> {
  for (const file of noticeCandidates()) {
    try {
      if ((await stat(file)).size > 8 * 1024 * 1024) continue
      return await readFile(file, 'utf8')
    } catch {
      // try the next place
    }
  }
  return null
}

interface FfmpegBuild {
  tag?: string
  asset?: string
}

/** BtbN release and FFmpeg source of the bundled build (vendor/ffmpeg/build.json, from fetch-ffmpeg). */
export function ffmpegBuildLinks(version: string, build: FfmpegBuild | null): AboutInfo['ffmpegBuild'] {
  const tag = build?.tag && /^[\w.-]{1,80}$/.test(build.tag) && build.tag !== 'latest' ? build.tag : ''
  const commit = /-g([0-9a-f]{7,40})(?:-|$)/.exec(version)?.[1]
  return {
    release: tag ? `https://github.com/BtbN/FFmpeg-Builds/releases/tag/${tag}` : 'https://github.com/BtbN/FFmpeg-Builds/releases',
    source: commit ? `https://github.com/FFmpeg/FFmpeg/tree/${commit}` : undefined,
    scripts: tag ? `https://github.com/BtbN/FFmpeg-Builds/tree/${tag}` : undefined
  }
}

function readBuild(ffmpegDir: string): FfmpegBuild | null {
  for (const file of [join(ffmpegDir, 'build.json'), join(ffmpegDir, '..', 'build.json')]) {
    if (!existsSync(file)) continue
    try {
      return JSON.parse(readFileSync(file, 'utf8')) as FfmpegBuild
    } catch {
      return null
    }
  }
  return null
}

export function registerAbout(cfg: { ff: Ffmpeg; ffmpegDir: string; settings: AppSettingsStore }): void {
  let ffmpegVersion: Promise<string> | null = null
  const ffVersion = (): Promise<string> =>
    (ffmpegVersion ??= cfg.ff
      .capture(['-hide_banner', '-version'])
      .then((out) => /ffmpeg version (\S+)/.exec(out.toString('utf8'))?.[1] ?? 'unknown')
      .catch(() => 'missing'))

  ipcMain.handle('about:info', async (): Promise<AboutInfo> => {
    const ffmpeg = await ffVersion()
    return {
      version: appVersion(),
      electron: process.versions.electron ?? '',
      chrome: process.versions.chrome ?? '',
      node: process.versions.node,
      ffmpeg,
      ffmpegBuild: ffmpegBuildLinks(ffmpeg, readBuild(cfg.ffmpegDir)),
      repo: REPO_URL,
      license: 'MIT'
    }
  })

  ipcMain.handle('about:notices', () => readNotices())

  // DIASHOW_UPDATE_URL points the check at another server (tests); development builds only check
  // automatically with it, so test runs and `npm run dev` don't ask GitHub.
  const url = process.env.DIASHOW_UPDATE_URL || LATEST_RELEASE_API
  const automatic = app.isPackaged || !!process.env.DIASHOW_UPDATE_URL
  const fetchImpl: FetchLike = (u, init) => net.fetch(u, { signal: init.signal, headers: init.headers })
  // one check of each kind at a time (the hint asks again when the title bar is shown anew)
  const running = new Map<boolean, Promise<UpdateStatus>>()
  ipcMain.handle('update:check', (_e, force: unknown): Promise<UpdateStatus> => {
    const manual = force === true
    if (!manual && !automatic) return Promise.resolve({ state: 'skipped', current: appVersion() })
    const busy = running.get(manual)
    if (busy) return busy
    const run = checkForUpdate({ current: appVersion(), settings: cfg.settings, fetch: fetchImpl, url, userAgent: `DiashowStudio/${appVersion()}` }, manual).finally(() =>
      running.delete(manual)
    )
    running.set(manual, run)
    return run
  })
}
